fn find_first_odd(a: &[i32]) -> (bool, usize) {
    for (i, &x) in a.iter().enumerate() {
        if x % 2 != 0 {
            return (true, i);
        }
    }
    (false, 0)
}

fn main() {
    let tests: &[&[i32]] = &[
        &[],
        &[2, 4, 6, 8],
        &[2, 3, 4, 5],
        &[-4, -3, -2, -1, 0],
        &[1, 2, 3],
    ];

    for &test in tests {
        let (found, idx) = find_first_odd(test);
        if found {
            println!("First odd in {:?} is at index {}: {}", test, idx, test[idx]);
        } else {
            println!("No odd in {:?}.", test);
        }
    }
}